import axios from "axios";
import React, { useEffect, useState } from "react";
import Cards from "./Cards";
import { NavLink } from "react-router-dom";

const SimilarMovie = ({ movieId }) => {
  const [data, setData] = useState([]);
  const idMovie = movieId;
  const [scrollPosition, setScrollPosition] = useState(0);

  useEffect(() => {
    const fetchData = async () => {
      if (movieId) {
        const res = await axios.get(
          `https://api.themoviedb.org/3/movie/${movieId}/recommendations?api_key=864b6602f4018630491e67fa714381e6&query=a&page=1&language=fr-FR`
        );
        setData(res.data.results);
      }
    };
    fetchData();
  }, [movieId]);
  const handleScroll = (direction) => {
    const container = document.querySelector(".similar-movies-container ");
    const scrollAmount = 200;
    if (direction === "left") {
      container.scrollLeft -= scrollAmount;
      setScrollPosition(container.scrollLeft);
    } else {
      container.scrollLeft += scrollAmount;
      setScrollPosition(container.scrollLeft);
    }
  };
  return (
    <div className="similar">
      {data.length > 0 ? <h4>Titres similaires</h4> : null}
      <div className="similar-movies-container">
        {data
          .filter((movie) => {
            if (
              movie.original_language === "en" ||
              movie.original_language === "fr"
            ) {
              return movie;
            } else {
              return null;
            }
          })
          .filter((movie) => {
            if (movie.poster_path) {
              return movie;
            } else {
              return null;
            }
          })
          .map((movie, index) => (
            <NavLink to={`/${movie.id}`}>
              <Cards key={index} movie={movie} />
            </NavLink>
          ))}
      </div>
      <button className="prev" onClick={() => handleScroll("left")}>
        <i className="fa-solid fa-angle-left"></i>
      </button>
      <button className="next" onClick={() => handleScroll("right")}>
        <i className="fa-solid fa-angle-right"></i>
      </button>
    </div>
  );
};

export default SimilarMovie;
